from pathlib import Path
import base64,json,re,hashlib,subprocess
R=Path('.'); O=Path('assets')
paths=['assets/hq-baby/'+t+'-'+k+'.webp' for t in ['animal','fantasy','fairy','yokai','dino'] for k in ['base','face','motion','food']]+['assets/pet-room-'+t+'.svg' for t in ['animal','fantasy','fairy','yokai','dino']]+['assets/pet-baby-food-types.svg','assets/pet-care-hairbrush.svg','assets/pet-care-cloth.svg','assets/pet-care-sponge.svg']
assets={p:{'type':'image/svg+xml' if p.endswith('.svg') else 'image/webp','data':base64.b64encode((R/p).read_bytes()).decode()} for p in paths}
assets['assets/pet-care-brush.svg']={'type':'image/svg+xml','data':base64.b64encode((O/'pet-care-brush.svg').read_bytes()).decode()}
css=(R/'pet-game.css').read_text()+'\n'+(R/'pet-hq.css').read_text()+'\n'+(R/'pet-brush.css').read_text()
renderer=(R/'pet-illustration.js').read_text()
page='''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>幼体5種族｜お手入れ v0.2.50</title><style>
*{box-sizing:border-box}body{margin:0;background:#111a23;color:#edf2f5;font:15px system-ui,sans-serif;--bg:#1d2a36;--line:#46535e;--muted:#a7b7c2;--good:#8dd5bc}main{max-width:650px;padding:16px;margin:auto}h1{font-size:21px;line-height:1.4;margin:0 0 6px}p{line-height:1.55}small,.note{color:#bdcbd3;font-size:12px}button{color:inherit;font:inherit;background:#253745;border:1px solid #516573;border-radius:12px;padding:12px;min-height:45px;cursor:pointer}button.primary{background:#387b68;border-color:#76bba3}button.active{outline:2px solid #b4dbca}nav{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0}nav button{flex:1}.qa-head{display:flex;align-items:center;justify-content:space-between;margin-top:16px}.qa-head h2{font-size:16px;margin:0}.qa-tag{font-size:12px;border:1px solid #607783;padding:4px 7px;border-radius:8px}.qa-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.qa-actions button{padding:12px 4px;font-size:14px}#brushBtn{grid-column:span 2}#status{font-size:13px;min-height:20px;color:#b8d4c9}.qa-zoom .pet-room{min-height:345px}.qa-zoom .pet-stage{min-height:280px}.qa-zoom .pet-stage .pet-character{scale:1.2;transform-origin:50% 88%}.qa-stage .pet-room{max-width:560px;margin:10px auto}.qa-foot{border-top:1px solid #405260;padding-top:10px} .pet-speech{box-sizing:border-box} .qa-hint{font-size:12px;margin:6px 0;color:#b8c8d0}
</style></head><body><main><h1>幼体5種族｜お手入れ v0.2.50</h1><p class="note">採用済みHQ素材を使用。保存なし・本番データに影響しません。</p><label>種族 <select id="species"><option value="fantasy">架空の生き物</option><option value="fairy">妖精風</option><option value="yokai">妖怪</option><option value="dino">恐竜</option><option value="animal">動物風（合格済みr1）</option></select></label><nav id="mode"><button data-mode="new" class="active">専用動作（試作）</button><button data-mode="old">従来動作</button></nav><div class="qa-head"><h2 id="heading">専用動作・2回のお手入れ</h2><button id="zoom" class="qa-tag" aria-pressed="false">拡大</button></div><div class="qa-stage"><div class="pet-room" id="petRoom" data-room-type="animal"><div class="pet-stage" id="petAvatar" aria-live="off"></div><p class="pet-speech" id="petSpeech" aria-live="polite">のんびり過ごしている。</p></div></div><div class="qa-actions"><button class="primary" id="brushBtn" data-action="brush">お手入れ</button><button data-action="idle">待機</button><button data-action="pet">なでる</button><button data-action="feed">ごはん</button><button data-action="rest">見守る</button></div><p id="status" aria-live="polite">待機中</p><p class="qa-hint">道具と接触位置、2回の動き、相棒の反応と待機復帰を確認してください。連続タップ・別操作への切り替えもできます。</p><p class="qa-foot note">比較範囲：幼体5種族。妖怪は既存の視線・しっぽを使い、閉眼しません。比較のため既存3操作も再生できます。愛情度・レベル・保存処理はありません。</p></main><script>
const embedded=__ASSETS__;const urls={};for(const [k,v] of Object.entries(embedded)){const str=atob(v.data),bytes=new Uint8Array(str.length);for(let i=0;i<str.length;i++)bytes[i]=str.charCodeAt(i);urls[k]=URL.createObjectURL(new Blob([bytes],{type:v.type}));}
function mapUrls(s){return s.replace(/url\\((['"]?)(?:\\.\\/)?(assets\\/[^)'"\\s]+)\\1\\)/g,(all,q,path)=>urls[path.split('?')[0]]?'url('+urls[path.split('?')[0]]+')':'none');}
const style=document.createElement('style');style.textContent=mapUrls(__CSS__);document.head.append(style);
__RENDERER__
const rawDraw=HAM.PetIllustration.draw;const draw=opt=>mapUrls(rawDraw(opt));
const stage=document.getElementById('petAvatar'),speech=document.getElementById('petSpeech'),status=document.getElementById('status');let species='fantasy',current='idle',mode='new',dir='front',timer=0,turn=0;const seq=['front','left','back','right','front'];const moods={idle:'idle',brush:'pet',pet:'pet',feed:'food',rest:'calm'};const replies={idle:'のんびり過ごしている。',brush:'気持ちよさそうにブラッシングを楽しんでいる。',pet:'うれしそうに目を細めた！',feed:'おいしそうにもぐもぐしている。',rest:'安心したように、のんびりしている。'};
function paint(restart=false){const mood=moods[current];let ch=stage.querySelector('.pet-character');if(!ch){ch=document.createElement('span');ch.className='pet-character';ch.dataset.type=species;ch.dataset.growth='baby';ch.dataset.bond='friendly';ch.setAttribute('role','img');ch.setAttribute('aria-label',species+'の幼体');stage.append(ch)}for(const k of Object.values(moods))ch.classList.toggle('pet-mood-'+k,k===mood);ch.dataset.action=current==='brush'&&mode==='new'?'brush':'';const facing=current==='idle'?dir:'front';if(ch.dataset.facing!==facing||!ch.querySelector('.pet-illustration')){ch.dataset.facing=facing;ch.innerHTML=draw({type:species,stage:'baby',direction:facing,mood,affection:30})}
if(restart&&!matchMedia('(prefers-reduced-motion: reduce)').matches){for(const anim of ch.querySelector('.pet-illustration').getAnimations({subtree:true})){if(/^(pet247-care-|brush250-)/.test(anim.animationName||'')){anim.currentTime=0;anim.play()}}}speech.textContent=current==='brush'&&mode==='old'?'従来のなでる共通反応。':(current==='brush'?HAM.PetIllustration.careReply(species):replies[current]);status.textContent=current==='idle'?'待機中':(current==='brush'?(mode==='new'?'専用動作：約2.6秒':'従来動作：約1.7秒'):'既存の基本操作');}
function activate(action){clearTimeout(timer);current=action;if(action!=='idle')dir='front';paint(true);if(action!=='idle'){const duration=action==='brush'&&mode==='new'?2700:action==='rest'?3200:1700;timer=setTimeout(()=>{current='idle';paint()},duration)}}
document.getElementById('species').onchange=e=>{species=e.target.value;document.getElementById('petRoom').dataset.roomType=species;stage.innerHTML='';activate('idle')};document.getElementById('petRoom').dataset.roomType=species;document.querySelector('.qa-actions').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)activate(b.dataset.action)});document.getElementById('mode').addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(!b)return;mode=b.dataset.mode;for(const el of document.querySelectorAll('[data-mode]'))el.classList.toggle('active',el===b);document.getElementById('heading').textContent=mode==='new'?'専用動作・2回のお手入れ':'従来動作・なでると共通';activate('idle')});document.getElementById('zoom').onclick=e=>{const on=document.body.classList.toggle('qa-zoom');e.target.textContent=on?'通常サイズ':'拡大';e.target.setAttribute('aria-pressed',String(on))};setInterval(()=>{if(current==='idle'&&!matchMedia('(prefers-reduced-motion: reduce)').matches){dir=seq[++turn%seq.length];paint()}},3500);paint();
</script></body></html>'''
# Use JSON literals to retain original renderer and CSS bytes; all actual image bytes embedded once.
page=page.replace('__ASSETS__',json.dumps(assets,separators=(',',':'))).replace('__CSS__',json.dumps(css)).replace('__RENDERER__',renderer)
# enforce actual HTML JS syntax
for script in re.findall(r'<script>(.*?)</script>',page,re.S):subprocess.run(['node','--check'],input=script.encode(),check=True,capture_output=True)
Path('artifacts').mkdir(exist_ok=True);p=Path('artifacts/pet_brushing_5_babies_v0250.html');p.write_text(page);print(p,len(p.read_bytes()),hashlib.sha256(p.read_bytes()).hexdigest())
